script.code:
final String CSV_OID   = '082811dd-d4c4-4b3f-b288-e06f89d3383e'   // RENIEC verificados (CSV)
final String CACHE_OID = 'c4d5e6f7-a8b9-0123-cdef-123456789abc'   // Oracle LAMB RENIEC Cache v1
final String NS = 'urn:upeu:midpoint:local'
if (focus == null) return null
def ext = { String n ->
    def v = basic.getExtensionPropertyValue(focus, new javax.xml.namespace.QName(NS, n))
    def s = v?.toString()?.trim()
    s ? s : null
}
def estadoActual = ext('dataQualityStatus')
def decision = 'sin_reniec'
def elegido = null
if (estadoActual == 'manual_override') {
    decision = 'manual_override'
} else {
    def cands = []
    if (ext('reniecVerifiedGivenName') && ext('reniecVerifiedFamilyName') && midpoint.hasLinkedAccount(CSV_OID)) {
        cands << [src: 'csv', giv: ext('reniecVerifiedGivenName'), fam: ext('reniecVerifiedFamilyName'), at: (ext('reniecVerifiedAt') ?: '')]
    }
    if (ext('reniecGivenName') && ext('reniecFamilyName') && midpoint.hasLinkedAccount(CACHE_OID)) {
        def d = ext('reniecValidationDate')
        cands << [src: 'cache', giv: ext('reniecGivenName'), fam: ext('reniecFamilyName'), at: (d ? d.take(10) : '')]
    }
    if (!cands.isEmpty()) {
        // más reciente primero; empate → csv (verificación explícita del lote aprobado)
        elegido = cands.max { a, b -> (a.at <=> b.at) ?: (a.src == 'csv' ? 1 : -1) }
        def lambFam = ext('lambFamilyName')
        def lambGiv = ext('lambGivenName')
        if (!lambFam || !lambGiv) {
            decision = 'sin_lamb'
        } else {
            // palabras normalizadas: sin tildes, minúsculas, guion/apóstrofo/punto/coma = separador, espacios colapsados
            def toks = { String x ->
                def t = java.text.Normalizer.normalize(x ?: '', java.text.Normalizer.Form.NFD).replaceAll('\\p{M}', '')
                t.toLowerCase(Locale.ROOT).replaceAll("[-'\u2019.,]", ' ').trim().split('\\s+').findAll { it } as List
            }
            // ¿la lista b aparece seguida, palabra por palabra, dentro de la lista a? (nunca subcadena)
            def contiene = { List a, List b ->
                if (b.isEmpty() || b.size() > a.size()) return false
                (0..(a.size() - b.size())).any { i -> a.subList(i, i + b.size()) == b }
            }
            def rf = toks(elegido.fam); def lf = toks(lambFam)
            boolean apellidos = !rf.isEmpty() && !lf.isEmpty() && (rf == lf || contiene(rf, lf) || contiene(lf, rf))
            def rg = toks(elegido.giv); def lg = toks(lambGiv)
            boolean primerNombre = !lg.isEmpty() && rg.contains(lg[0])
            decision = ((apellidos && primerNombre) ? 'reniec_name:' : 'mismatch:') + elegido.src
        }
    }
}
switch (campo) {
    case 'decision':
        return decision
    case 'givenName':
        if (decision == 'manual_override') return focus.givenName?.orig
        return decision.startsWith('reniec_name') ? elegido.giv : ext('lambGivenName')
    case 'familyName':
        if (decision == 'manual_override') return focus.familyName?.orig
        return decision.startsWith('reniec_name') ? elegido.fam : ext('lambFamilyName')
    case 'estado':
        if (decision.startsWith('reniec_name')) return 'reniec_name'
        if (decision.startsWith('mismatch')) return 'mismatch'
        // sin RENIEC vigente: si antes lo había, pasa a pending; si no, se deja como está
        if (decision == 'sin_reniec' && (estadoActual == 'reniec_name' || estadoActual == 'mismatch')) return 'pending'
        return estadoActual
    case 'verifiedAt':
        return decision.startsWith('reniec_name') ? (elegido.at ?: null) : null
    default:
        throw new IllegalArgumentException('upeuNombreOficial.resolver: campo desconocido ' + campo)
}
